<?php
/** Disposable DB proof that notification failure cannot unassign or hide a matched booking. */
if(getenv('DZN_BOOKING_NOTIFICATION_INDEPENDENCE')!=='authority'||!defined('WP_CLI')||!WP_CLI||!in_array(wp_get_environment_type(),array('local','development'),true)){fwrite(STDERR,"Booking notification independence runtime refused.\n");exit(1);}
use Delnavazan\Platform\Core\Application\BookingTeacherDeliveryService;
use Delnavazan\Platform\Core\Support\Identifier;
use Delnavazan\Platform\Integrations\BookingStudentNotificationWorker;

global $wpdb;$p=$wpdb->prefix.'dzn_';$now=gmdate('Y-m-d H:i:s');$suffix=strtolower(wp_generate_password(10,false,false));
$assert=static function(bool $ok,string $message):void{if(!$ok)throw new RuntimeException($message);};
$wpdb->insert($p.'instruments',array('uid'=>Identifier::uid(),'reference_code'=>'DZN-INSTR-NOTIF-'.strtoupper($suffix),'slug'=>'notif-'.$suffix,'name_fa'=>'آزمون','name_en'=>'Notify','status'=>'active','created_at'=>$now,'updated_at'=>$now));$instrument=(int)$wpdb->insert_id;
$wpdb->insert($p.'courses',array('uid'=>Identifier::uid(),'reference_code'=>'DZN-COURSE-NOTIF-'.strtoupper($suffix),'instrument_id'=>$instrument,'name_fa'=>'آزمون','name_en'=>'Notify','course_type'=>'introductory','status'=>'active','default_duration_minutes'=>30,'default_buffer_minutes'=>15,'created_at'=>$now,'updated_at'=>$now));$course=(int)$wpdb->insert_id;
$wpdb->insert($p.'students',array('uid'=>Identifier::uid(),'reference_code'=>'DZN-STU-NOTIF-'.strtoupper($suffix),'status'=>'active','display_name'=>'Synthetic Student','email'=>'notif-student-'.$suffix.'@example.invalid','phone'=>'+61400000000','country_code'=>'AU','city'=>'Brisbane','timezone'=>'UTC','locale'=>'en','calendar_preference'=>'auto','created_at'=>$now,'updated_at'=>$now));$student=(int)$wpdb->insert_id;
$userId=wp_insert_user(array('user_login'=>'notif-teacher-'.$suffix,'user_pass'=>wp_generate_password(32,true,true),'user_email'=>'notif-teacher-'.$suffix.'@example.invalid','role'=>'subscriber','display_name'=>'Synthetic Teacher'));if(is_wp_error($userId))throw new RuntimeException('Teacher user failed');$userId=(int)$userId;
$wpdb->insert($p.'teachers',array('uid'=>Identifier::uid(),'reference_code'=>'DZN-TEACH-NOTIF-'.strtoupper($suffix),'status'=>'active','display_name'=>'Synthetic Teacher','timezone'=>'UTC','email'=>'not-an-email','wordpress_user_id'=>$userId,'created_at'=>$now,'updated_at'=>$now));$teacher=(int)$wpdb->insert_id;
$wpdb->insert($p.'teacher_principal_links',array('teacher_id'=>$teacher,'wordpress_user_id'=>$userId,'status'=>'active','linked_at'=>$now,'linked_by'=>1));
$wpdb->insert($p.'teacher_onboarding_states',array('teacher_id'=>$teacher,'state'=>'active','readiness_state'=>'ready','profile_state'=>'complete','availability_state'=>'complete','agreement_state'=>'not_required','activated_at'=>$now,'version'=>1,'created_at'=>$now,'updated_at'=>$now,'created_by'=>1,'updated_by'=>1));
$wpdb->insert($p.'teacher_availability_profiles',array('teacher_id'=>$teacher,'timezone'=>'UTC','status'=>'active','version'=>1,'created_at'=>$now,'updated_at'=>$now,'created_by'=>1,'updated_by'=>1));
$wpdb->insert($p.'booking_requests',array('uid'=>Identifier::uid(),'reference_code'=>'REQ-NOTIF-'.strtoupper($suffix),'student_id'=>$student,'requested_instrument_id'=>$instrument,'selected_intro_course_id'=>$course,'lifecycle_status'=>'submitted','resolution_state'=>'unresolved','retention_due_at'=>gmdate('Y-m-d H:i:s',strtotime('+24 months',strtotime($now.' UTC'))),'version'=>1,'created_at'=>$now,'updated_at'=>$now));$request=(int)$wpdb->insert_id;
$start=gmdate('Y-m-d H:i:s',strtotime('+10 days 10:00:00 UTC'));$end=gmdate('Y-m-d H:i:s',strtotime($start.' UTC +30 minutes'));$occupied=gmdate('Y-m-d H:i:s',strtotime($start.' UTC +45 minutes'));
$wpdb->insert($p.'booking_request_contact_snapshots',array('booking_request_id'=>$request,'snapshot_sequence'=>1,'full_name'=>'Synthetic Student','email'=>'notif-student-'.$suffix.'@example.invalid','mobile'=>'+61400000000','country'=>'AU','city'=>'Brisbane','timezone'=>'UTC','communication_language'=>'en','whatsapp_same_as_mobile'=>1,'whatsapp_number'=>'+61400000000','privacy_notice_version'=>'2026-09-05','privacy_notice_accepted'=>1,'privacy_notice_accepted_at'=>$now,'submission_source'=>'synthetic_notification_independence','created_at'=>$now));
$wpdb->insert($p.'booking_request_requested_times',array('booking_request_id'=>$request,'sequence_number'=>1,'local_date'=>substr($start,0,10),'local_start_time'=>substr($start,11),'timezone'=>'UTC','starts_at_utc'=>$start,'instructional_ends_at_utc'=>$end,'occupied_ends_at_utc'=>$occupied,'instructional_duration_minutes'=>30,'buffer_minutes'=>15,'version'=>1,'created_at'=>$now));$time=(int)$wpdb->insert_id;
$wpdb->insert($p.'booking_request_teacher_deliveries',array('uid'=>Identifier::uid(),'booking_request_id'=>$request,'requested_time_id'=>$time,'teacher_id'=>$teacher,'state'=>'pending_request','match_strength'=>'strong','created_at'=>$now,'updated_at'=>$now));$delivery=(int)$wpdb->insert_id;
$wpdb->insert($p.'booking_request_student_notifications',array('uid'=>Identifier::uid(),'delivery_id'=>$delivery,'confirmation_id'=>null,'notification_kind'=>'requested_teacher','state'=>'queued','attempt_count'=>0,'next_attempt_at'=>$now,'lease_token_digest'=>null,'lease_expires_at'=>null,'last_error_code'=>null,'handed_off_at'=>null,'created_at'=>$now,'updated_at'=>$now));$notification=(int)$wpdb->insert_id;
$result=BookingStudentNotificationWorker::dispatch($notification);
$assert(($result['state']??'')==='failed','The invalid recipient fixture did not fail the notification.');
$assert((string)$wpdb->get_var($wpdb->prepare("SELECT state FROM {$p}booking_request_teacher_deliveries WHERE id=%d",$delivery))==='pending_request','Notification failure changed the Teacher delivery state.');
$row=$wpdb->get_row($wpdb->prepare("SELECT lifecycle_status,resolution_state FROM {$p}booking_requests WHERE id=%d",$request));
$assert($row&&(string)$row->lifecycle_status==='submitted'&&(string)$row->resolution_state==='unresolved','Notification failure changed the booking request state.');
wp_set_current_user($userId);
$pending=(new BookingTeacherDeliveryService())->ownPending();
$assert(count($pending)===1&&(int)$pending[0]->booking_request_id===$request,'Notification failure hid the pending match from the Teacher portal.');
echo wp_json_encode(array('notification'=>'failed_as_expected','delivery'=>'pending_request','request'=>'submitted_unresolved','teacher_portal'=>'match_visible')) . "\n";
